import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
} from 'recharts';
import { MonthlyVisitorData, StoreConfig, StoreId } from '../types';

interface VisitorsChartProps {
  data?: readonly MonthlyVisitorData[];
  stores?: StoreConfig[];
  onToggleStore?: (storeId: StoreId) => void;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    name: string;
    value: number;
    color: string;
    dataKey: string;
  }>;
  label?: string;
  stores: StoreConfig[];
}

const CustomTooltip = ({ active, payload, label, stores }: CustomTooltipProps) => {
  if (!active || !payload || payload.length === 0) {
    return null;
  }

  return (
    <div className="custom-chart-tooltip">
      <div className="tooltip-title">{label} 来客数</div>
      {payload.map((item) => {
        const storeConfig = stores.find((s) => s.id === item.dataKey);
        const storeName = storeConfig ? storeConfig.name : item.name;
        return (
          <div key={item.dataKey} className="tooltip-row">
            <span className="tooltip-item-label">
              <span
                className="legend-color-box"
                style={{ backgroundColor: item.color }}
              />
              {storeName}
            </span>
            <span className="tooltip-item-val">
              {item.value.toLocaleString()} 人
            </span>
          </div>
        );
      })}
    </div>
  );
};

const VisitorsChart = ({
  data = [],
  stores = [],
  onToggleStore,
}: VisitorsChartProps) => {
  const activeStores = stores.filter((store) => store.active);

  return (
    <div className="card chart-card">
      <div className="chart-header">
        <h2 className="chart-title">月別来客数推移（年間）</h2>
        <div className="chart-legend-custom">
          <div className="btn-group">
            {stores.map((store) => {
              const isSelected = store.active;
              const buttonClass = isSelected
                ? 'toggle-btn toggle-btn-active'
                : 'toggle-btn';

              return (
                <button
                  key={store.id}
                  type="button"
                  className={buttonClass}
                  onClick={() => onToggleStore?.(store.id)}
                  title={`${store.name}の表示/非表示を切り替え`}
                  aria-pressed={isSelected}
                >
                  <span
                    className="legend-color-box"
                    style={{
                      backgroundColor: isSelected ? store.color : '#cbd5e1',
                    }}
                  />
                  <span className="legend-label">{store.name}</span>
                </button>
              );
            })}
          </div>
        </div>
      </div>

      <div style={{ width: '100%', height: 380 }}>
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={data as MonthlyVisitorData[]}
            margin={{ top: 12, right: 24, left: 10, bottom: 8 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
            <XAxis
              dataKey="month"
              tickLine={false}
              axisLine={{ stroke: '#cbd5e1' }}
              tick={{ fill: '#64748b', fontSize: 12 }}
            />
            <YAxis
              tickLine={false}
              axisLine={{ stroke: '#cbd5e1' }}
              tick={{ fill: '#64748b', fontSize: 12 }}
              tickFormatter={(val: number) => `${(val / 1000).toFixed(0)}k`}
              domain={['auto', 'auto']}
            />
            <Tooltip content={<CustomTooltip stores={stores} />} />
            {stores.map((store) => {
              if (!store.active) return null;
              return (
                <Line
                  key={store.id}
                  type="monotone"
                  dataKey={store.id}
                  name={store.name}
                  stroke={store.color}
                  strokeWidth={2.5}
                  dot={{ r: 4, fill: '#ffffff', stroke: store.color, strokeWidth: 2 }}
                  activeDot={{ r: 6, stroke: store.color, strokeWidth: 2 }}
                  animationDuration={600}
                />
              );
            })}
          </LineChart>
        </ResponsiveContainer>
      </div>
      {activeStores.length === 0 && (
        <p
          className="header-desc"
          style={{ textAlign: 'center', marginTop: '16px' }}
        >
          上のボタンをクリックして、表示する店舗を選択してください。
        </p>
      )}
    </div>
  );
};

export default VisitorsChart;

import { StoreConfig, StoreSummary } from '../types';

interface StatsCardsProps {
  summaries?: StoreSummary[];
  stores?: StoreConfig[];
}

const StatsCards = ({ summaries = [], stores }: StatsCardsProps) => {
  if (summaries.length === 0) {
    return (
      <div className="card">
        <p className="header-desc">表示できる統計データがありません。</p>
      </div>
    );
  }

  return (
    <div className="stats-grid">
      {summaries.map((summary) => {
        const storeConfig = stores?.find((s) => s.id === summary.id);
        const isActive = storeConfig !== undefined ? storeConfig.active : true;

        return (
          <div
            key={summary.id}
            className="stat-card"
            style={{
              opacity: isActive ? 1 : 0.45,
              transition: 'opacity 0.2s ease',
            }}
          >
            <div className="stat-header">
              <span
                className="stat-store-dot"
                style={{ backgroundColor: summary.color }}
              />
              <span className="stat-store-name">{summary.name}</span>
            </div>

            <div className="stat-main-val">
              {summary.total.toLocaleString()}
              <span className="stat-unit">人 / 年</span>
            </div>

            <div className="stat-details">
              <div className="stat-row">
                <span className="stat-sublabel">月間平均来客数</span>
                <span className="stat-subval">
                  {summary.average.toLocaleString()} 人
                </span>
              </div>
              <div className="stat-row">
                <span className="stat-sublabel">最多来客月（ピーク）</span>
                <span className="stat-subval">
                  {summary.peakMonth} ({summary.peakValue.toLocaleString()} 人)
                </span>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default StatsCards;

import { useState, useMemo } from 'react';
import { MonthlyVisitorData, StoreConfig, StoreId, StoreSummary } from './types';
import { INITIAL_STORES, MONTHLY_VISITORS_DATA } from './data';
import VisitorsChart from './components/VisitorsChart';
import StatsCards from './components/StatsCards';

const getStoreVisitors = (row: MonthlyVisitorData, storeId: StoreId): number => {
  return row[storeId];
};

const App = () => {
  const [stores, setStores] = useState<StoreConfig[]>(INITIAL_STORES);

  const handleToggleStore = (storeId: StoreId) => {
    setStores((prevStores) =>
      prevStores.map((store) =>
        store.id === storeId ? { ...store, active: !store.active } : store
      )
    );
  };

  // 各店舗のサマリー計算（年間合計、月平均、ピーク月・ピーク値）
  const summaries: StoreSummary[] = useMemo(() => {
    return stores.map((store) => {
      let total = 0;
      let peakValue = -Infinity;
      let peakMonth = '';

      MONTHLY_VISITORS_DATA.forEach((row) => {
        const val = getStoreVisitors(row, store.id);
        total += val;
        if (val > peakValue) {
          peakValue = val;
          peakMonth = row.month;
        }
      });

      const average = Math.round(total / MONTHLY_VISITORS_DATA.length);

      return {
        id: store.id,
        name: store.name,
        color: store.color,
        total,
        average,
        peakMonth,
        peakValue,
      };
    });
  }, [stores]);

  // ピーク月判定用マップ（店舗ごと）
  const peakMonthMap = useMemo(() => {
    const map: Record<StoreId, string> = {
      shinjuku: '',
      shibuya: '',
      ikebukuro: '',
    };
    summaries.forEach((s) => {
      map[s.id] = s.peakMonth;
    });
    return map;
  }, [summaries]);

  // 全店舗の年間総合計
  const grandTotal = useMemo(() => {
    return summaries.reduce((acc, curr) => acc + curr.total, 0);
  }, [summaries]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">店舗別月間来客数ダッシュボード</h1>
        <p className="header-desc">
          新宿店・渋谷店・池袋店の年間12ヶ月にわたる来客推移・月別実績を比較分析できます。
        </p>
      </header>

      <main className="main-layout">
        {/* サマリーカード一覧 */}
        <StatsCards summaries={summaries} stores={stores} />

        {/* recharts による折れ線グラフ */}
        <VisitorsChart
          data={MONTHLY_VISITORS_DATA}
          stores={stores}
          onToggleStore={handleToggleStore}
        />

        {/* 詳細データテーブル */}
        <div className="card table-card">
          <h2 className="chart-title">月別来客数 詳細データ</h2>
          <div className="table-wrapper">
            <table className="data-table">
              <thead>
                <tr>
                  <th className="th">月</th>
                  {stores.map((store) => (
                    <th
                      key={store.id}
                      className={`th ${!store.active ? 'is-inactive' : ''}`}
                      style={{
                        opacity: store.active ? 1 : 0.45,
                        transition: 'opacity 0.2s ease',
                      }}
                    >
                      <span
                        className="legend-color-box"
                        style={{
                          backgroundColor: store.active ? store.color : '#cbd5e1',
                          marginRight: 6,
                          verticalAlign: 'middle',
                        }}
                      />
                      {store.name}
                    </th>
                  ))}
                  <th className="th">3店舗合計</th>
                </tr>
              </thead>
              <tbody>
                {MONTHLY_VISITORS_DATA.map((row) => {
                  const monthlyTotal = row.shinjuku + row.shibuya + row.ikebukuro;

                  return (
                    <tr key={row.month}>
                      <td className="td" style={{ fontWeight: 600 }}>
                        {row.month}
                      </td>
                      {stores.map((store) => {
                        const val = getStoreVisitors(row, store.id);
                        const isPeak = peakMonthMap[store.id] === row.month;

                        return (
                          <td
                            key={store.id}
                            className={`td ${!store.active ? 'is-inactive' : ''}`}
                            style={{
                              opacity: store.active ? 1 : 0.45,
                              transition: 'opacity 0.2s ease',
                            }}
                          >
                            {val.toLocaleString()} 人
                            {isPeak && <span className="badge-peak">最高</span>}
                          </td>
                        );
                      })}
                      <td className="td" style={{ fontWeight: 700, color: '#0f172a' }}>
                        {monthlyTotal.toLocaleString()} 人
                      </td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr style={{ backgroundColor: '#f8fafc', borderTop: '2px solid var(--color-border)' }}>
                  <td className="td" style={{ fontWeight: 700 }}>
                    年間合計
                  </td>
                  {stores.map((store) => {
                    const summary = summaries.find((s) => s.id === store.id);
                    const total = summary ? summary.total : 0;

                    return (
                      <td
                        key={store.id}
                        className={`td ${!store.active ? 'is-inactive' : ''}`}
                        style={{
                          fontWeight: 700,
                          opacity: store.active ? 1 : 0.45,
                          transition: 'opacity 0.2s ease',
                        }}
                      >
                        {total.toLocaleString()} 人
                      </td>
                    );
                  })}
                  <td className="td" style={{ fontWeight: 800, color: 'var(--color-text-main)' }}>
                    {grandTotal.toLocaleString()} 人
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;
